messages.content:
Tool response:
Tool: record_exam_attempt
Description: Record a new exam attempt for a candidate
Parameters:
    {
      "type": "object",
      "properties": {
        "candidate_id": {
          "type": "integer",
          "title": "Candidate Id"
        },
        "certification_id": {
          "type": "integer",
          "title": "Certification Id"
        },
        "test_center_id": {
          "type": "integer",
          "title": "Test Center Id"
        },
        "attempt_date": {
          "type": "string",
          "title": "Attempt Date"
        },
        "score": {
          "type": "number",
          "title": "Score"
        },
        "result": {
          "type": "string",
          "enum": [
            "pass",
            "fail",
            "pending"
          ],
          "title": "Result"
        }
      },
      "required": [
        "candidate_id",
        "certification_id",
        "test_center_id",
        "attempt_date",
        "score",
        "result"
      ]
    }
